function Remove-Tree($root) {
  if (-not (Test-Path $root)) { return "$root absent" }
  Get-ChildItem $root -Recurse -Force -Attributes ReparsePoint -ErrorAction SilentlyContinue | ForEach-Object { if ($_.PSIsContainer) { [System.IO.Directory]::Delete($_.FullName, $false) } else { [System.IO.File]::Delete($_.FullName) } }
  if ((Get-ChildItem $root -Recurse -Force -Attributes ReparsePoint -ErrorAction SilentlyContinue | Measure-Object).Count -ne 0) { return "$root SKIPPED, links remain" }
  Remove-Item $root -Recurse -Force -ErrorAction SilentlyContinue
  if (Test-Path $root) { "$root partly removed" } else { "$root removed" }
}
